<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.rp-ui form').forEach(function(form){form.addEventListener('submit',function(){const fields={};form.querySelectorAll('.rp-action-check').forEach(function(c){const id=c.dataset.field;(fields[id]||(fields[id]=[]));if(c.checked)fields[id].push(c.value);});Object.keys(fields).forEach(function(id){const f=document.getElementById(id);if(f)f.value=fields[id].join(',');});});});});</script>
